const express=require('express');
const pool=require('../config/db');
const {autenticar,exigirPapel,exigirAssinatura,exigirStepUp}=require('../middlewares/auth');
const {exigirRecurso}=require('../services/planos');
const {intId,cleanText,finiteMoney,isoDate,safeHttpUrl}=require('../utils/validation');
const {externalSignal}=require('../utils/http');
const {recomputeComanda,notifyWaitlistForSlot,recordStockMovement,consumeServiceInputs}=require('../services/advancedOps');
const router=express.Router();
router.use(autenticar,exigirAssinatura);
const t=req=>req.usuario.barbearia_id;
const staff=exigirPapel('dono','gerente','recepcao');
const manager=exigirPapel('dono','gerente');
const money=(v,max=1_000_000)=>finiteMoney(v??0,{min:0,max});

// ---------- Comandas ----------
router.get('/comandas',staff,exigirRecurso('comandas'),async(req,res)=>{try{const status=['aberta','fechada','cancelada'].includes(req.query.status)?req.query.status:null,vals=[t(req)],where=['c.barbearia_id=$1'];if(status){vals.push(status);where.push(`c.status=$${vals.length}`)}const r=await pool.query(`SELECT c.*,cl.nome cliente,b.nome barbeiro,a.data,a.horario FROM comandas c LEFT JOIN clientes cl ON cl.id=c.cliente_id AND cl.barbearia_id=c.barbearia_id LEFT JOIN barbeiros b ON b.id=c.barbeiro_id AND b.barbearia_id=c.barbearia_id LEFT JOIN agendamentos a ON a.id=c.agendamento_id AND a.barbearia_id=c.barbearia_id WHERE ${where.join(' AND ')} ORDER BY CASE c.status WHEN 'aberta' THEN 0 ELSE 1 END,c.atualizado_em DESC LIMIT 300`,vals);res.json(r.rows)}catch(e){console.error(e);res.status(500).json({erro:'Erro ao listar comandas'})}});
router.post('/comandas',staff,exigirRecurso('comandas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const x=req.body||{},tenant=t(req),agId=x.agendamento_id?intId(x.agendamento_id):null,clienteId=x.cliente_id?intId(x.cliente_id):null,barbeiroId=x.barbeiro_id?intId(x.barbeiro_id):null,obs=cleanText(x.observacoes,1000)||null;let cli=clienteId,barb=barbeiroId,ag=null;if(agId){ag=(await c.query(`SELECT a.*,s.nome servico,s.preco FROM agendamentos a JOIN servicos s ON s.id=a.servico_id AND s.barbearia_id=a.barbearia_id WHERE a.id=$1 AND a.barbearia_id=$2 FOR UPDATE`,[agId,tenant])).rows[0];if(!ag)throw new Error('Agendamento não encontrado');if(['cancelado','nao_compareceu'].includes(ag.status))throw new Error('Agendamento cancelado/ausente não pode abrir comanda');cli=ag.cliente_id;barb=ag.barbeiro_id;const existing=(await c.query(`SELECT * FROM comandas WHERE barbearia_id=$1 AND agendamento_id=$2`,[tenant,agId])).rows[0];if(existing){await c.query('COMMIT');return res.json(existing)}}if(cli&&!(await c.query(`SELECT 1 FROM clientes WHERE id=$1 AND barbearia_id=$2`,[cli,tenant])).rowCount)throw new Error('Cliente inválido');if(barb&&!(await c.query(`SELECT 1 FROM barbeiros WHERE id=$1 AND barbearia_id=$2`,[barb,tenant])).rowCount)throw new Error('Barbeiro inválido');const cmd=(await c.query(`INSERT INTO comandas(barbearia_id,cliente_id,barbeiro_id,agendamento_id,observacoes) VALUES($1,$2,$3,$4,$5) RETURNING *`,[tenant,cli||null,barb||null,agId||null,obs])).rows[0];if(ag){const unit=Number(ag.valor_final??ag.valor_servico??ag.preco??0);await c.query(`INSERT INTO comanda_itens(comanda_id,barbearia_id,tipo,referencia_id,descricao,quantidade,valor_unitario,subtotal) VALUES($1,$2,'servico',$3,$4,1,$5,$5)`,[cmd.id,tenant,ag.servico_id,cleanText(ag.servico,200),unit]);await c.query(`UPDATE agendamentos SET status=CASE WHEN status IN ('agendado','confirmado') THEN 'em_atendimento' ELSE status END WHERE id=$1 AND barbearia_id=$2`,[agId,tenant])}await recomputeComanda(c,cmd.id,tenant);await c.query('COMMIT');res.status(201).json((await pool.query(`SELECT * FROM comandas WHERE id=$1 AND barbearia_id=$2`,[cmd.id,tenant])).rows[0])}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message||'Erro ao abrir comanda'})}finally{c.release()}});
router.get('/comandas/:id',staff,exigirRecurso('comandas'),async(req,res)=>{try{const id=intId(req.params.id);if(!id)return res.status(400).json({erro:'Comanda inválida'});const cmd=(await pool.query(`SELECT c.*,cl.nome cliente,b.nome barbeiro FROM comandas c LEFT JOIN clientes cl ON cl.id=c.cliente_id AND cl.barbearia_id=c.barbearia_id LEFT JOIN barbeiros b ON b.id=c.barbeiro_id AND b.barbearia_id=c.barbearia_id WHERE c.id=$1 AND c.barbearia_id=$2`,[id,t(req)])).rows[0];if(!cmd)return res.status(404).json({erro:'Comanda não encontrada'});const itens=(await pool.query(`SELECT * FROM comanda_itens WHERE comanda_id=$1 AND barbearia_id=$2 ORDER BY id`,[id,t(req)])).rows;res.json({...cmd,itens})}catch(e){res.status(500).json({erro:'Erro ao carregar comanda'})}});
router.post('/comandas/:id/itens',staff,exigirRecurso('comandas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=intId(req.params.id),tenant=t(req),x=req.body||{},tipo=String(x.tipo||''),ref=x.referencia_id?intId(x.referencia_id):null,q=Number(x.quantidade||1);if(!id||!['servico','produto','extra'].includes(tipo)||!Number.isFinite(q)||q<=0||q>1000)throw new Error('Item inválido');const cmd=(await c.query(`SELECT * FROM comandas WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[id,tenant])).rows[0];if(!cmd||cmd.status!=='aberta')throw new Error('Comanda não está aberta');let descricao,unit;if(tipo==='produto'){const p=(await c.query(`SELECT id,nome,preco,estoque FROM produtos WHERE id=$1 AND barbearia_id=$2 AND ativo=true`,[ref,tenant])).rows[0];if(!p)throw new Error('Produto inválido');if(Number(p.estoque)<q)throw new Error('Estoque insuficiente');descricao=p.nome;unit=Number(p.preco)}else if(tipo==='servico'){const s=(await c.query(`SELECT id,nome,preco FROM servicos WHERE id=$1 AND barbearia_id=$2 AND ativo=true`,[ref,tenant])).rows[0];if(!s)throw new Error('Serviço inválido');descricao=s.nome;unit=Number(s.preco)}else{descricao=cleanText(x.descricao,200,{required:true});unit=money(x.valor_unitario);if(!descricao||unit===null)throw new Error('Informe descrição e valor do extra')}const sub=Number((unit*q).toFixed(2));const item=(await c.query(`INSERT INTO comanda_itens(comanda_id,barbearia_id,tipo,referencia_id,descricao,quantidade,valor_unitario,subtotal) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *`,[id,tenant,tipo,ref||null,descricao,q,unit,sub])).rows[0];await recomputeComanda(c,id,tenant);await c.query('COMMIT');res.status(201).json(item)}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message||'Erro ao adicionar item'})}finally{c.release()}});
router.delete('/comandas/:id/itens/:itemId',staff,exigirRecurso('comandas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=intId(req.params.id),itemId=intId(req.params.itemId),tenant=t(req);const cmd=(await c.query(`SELECT status FROM comandas WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[id,tenant])).rows[0];if(!cmd||cmd.status!=='aberta')throw new Error('Comanda não está aberta');const d=await c.query(`DELETE FROM comanda_itens WHERE id=$1 AND comanda_id=$2 AND barbearia_id=$3 RETURNING id`,[itemId,id,tenant]);if(!d.rowCount)throw new Error('Item não encontrado');await recomputeComanda(c,id,tenant);await c.query('COMMIT');res.json({mensagem:'Item removido'})}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});
router.patch('/comandas/:id',staff,exigirRecurso('comandas'),async(req,res)=>{try{const id=intId(req.params.id),des=money(req.body.desconto);if(!id||des===null)return res.status(400).json({erro:'Desconto inválido'});const cmd=(await pool.query(`SELECT subtotal_servicos,subtotal_produtos,status FROM comandas WHERE id=$1 AND barbearia_id=$2`,[id,t(req)])).rows[0];if(!cmd||cmd.status!=='aberta')return res.status(409).json({erro:'Comanda não está aberta'});if(des>Number(cmd.subtotal_servicos)+Number(cmd.subtotal_produtos))return res.status(400).json({erro:'Desconto maior que a comanda'});await pool.query(`UPDATE comandas SET desconto=$1,atualizado_em=NOW() WHERE id=$2 AND barbearia_id=$3`,[des,id,t(req)]);await recomputeComanda(pool,id,t(req));res.json((await pool.query(`SELECT * FROM comandas WHERE id=$1 AND barbearia_id=$2`,[id,t(req)])).rows[0])}catch(e){res.status(500).json({erro:'Erro ao atualizar comanda'})}});
router.post('/comandas/:id/fechar',staff,exigirRecurso('comandas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=intId(req.params.id),tenant=t(req),forma=String(req.body.forma_pagamento||'dinheiro');if(!id||!['dinheiro','pix','cartao','mercado_pago','pix_manual'].includes(forma))throw new Error('Forma de pagamento inválida');const cmd=(await c.query(`SELECT * FROM comandas WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[id,tenant])).rows[0];if(!cmd||cmd.status!=='aberta')throw new Error('Comanda não está aberta');await recomputeComanda(c,id,tenant);const fresh=(await c.query(`SELECT * FROM comandas WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[id,tenant])).rows[0],itens=(await c.query(`SELECT * FROM comanda_itens WHERE comanda_id=$1 AND barbearia_id=$2 ORDER BY id`,[id,tenant])).rows;if(!itens.length)throw new Error('Adicione itens antes de fechar');for(const it of itens.filter(x=>x.tipo==='produto')){const p=(await c.query(`SELECT estoque FROM produtos WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[it.referencia_id,tenant])).rows[0];if(!p||Number(p.estoque)<Number(it.quantidade))throw new Error(`Estoque insuficiente para ${it.descricao}`)}let ag=null,pre=0;if(fresh.agendamento_id){ag=(await c.query(`SELECT * FROM agendamentos WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[fresh.agendamento_id,tenant])).rows[0];if(!ag)throw new Error('Agendamento vinculado não encontrado');if((await c.query(`SELECT 1 FROM vendas WHERE barbearia_id=$1 AND agendamento_id=$2 AND status='finalizada'`,[tenant,fresh.agendamento_id])).rowCount)throw new Error('Agendamento já possui venda finalizada');pre=Math.max(0,Math.min(Number(ag.valor_pago||0),Number(fresh.subtotal_servicos||0)))}const recebido=Math.max(0,Number(fresh.total)-pre);const vr=(await c.query(`INSERT INTO vendas(barbearia_id,cliente_id,barbeiro_id,agendamento_id,forma_pagamento,status,total,desconto,subtotal_servicos,subtotal_produtos,valor_pre_pago,valor_recebido) VALUES($1,$2,$3,$4,$5,'finalizada',$6,$7,$8,$9,$10,$11) RETURNING id`,[tenant,fresh.cliente_id,fresh.barbeiro_id,fresh.agendamento_id,forma,Number(fresh.total),Number(fresh.desconto),Number(fresh.subtotal_servicos),Number(fresh.subtotal_produtos),pre,recebido])).rows[0];for(const it of itens){await c.query(`INSERT INTO venda_itens(venda_id,tipo,referencia_id,descricao,quantidade,valor_unitario,subtotal) VALUES($1,$2,$3,$4,$5,$6,$7)`,[vr.id,it.tipo==='extra'?'servico':it.tipo,it.referencia_id,it.descricao,it.quantidade,it.valor_unitario,it.subtotal]);if(it.tipo==='produto'){const pr=(await c.query(`SELECT estoque,custo FROM produtos WHERE id=$1 AND barbearia_id=$2 FOR UPDATE`,[it.referencia_id,tenant])).rows[0],before=Number(pr.estoque),after=Number((before-Number(it.quantidade)).toFixed(3));await c.query(`UPDATE produtos SET estoque=$1,atualizado_em=NOW() WHERE id=$2 AND barbearia_id=$3`,[after,it.referencia_id,tenant]);await recordStockMovement(c,{barbeariaId:tenant,produtoId:it.referencia_id,tipo:'venda',quantidade:-Number(it.quantidade),estoqueAnterior:before,estoquePosterior:after,custoUnitario:Number(pr.custo||0),referenciaTipo:'venda',referenciaId:vr.id,observacoes:'Saída pela comanda',usuarioId:req.usuario.id})}}await consumeServiceInputs(c,{barbeariaId:tenant,serviceItems:itens.filter(x=>x.tipo==='servico'),referenceType:'venda',referenceId:vr.id,usuarioId:req.usuario.id});if(ag){const serviceTotal=Number(fresh.subtotal_servicos||0);await c.query(`UPDATE agendamentos SET status='concluido',status_pagamento=CASE WHEN $1+0.009 >= $2 THEN 'pago' WHEN $1>0 THEN 'parcial' ELSE 'aguardando' END,valor_pago=$1,valor_final=$2 WHERE id=$3 AND barbearia_id=$4`,[serviceTotal,serviceTotal,fresh.agendamento_id,tenant])}if(fresh.cliente_id){const fc=(await c.query(`SELECT * FROM fidelidade_config WHERE barbearia_id=$1 AND ativo=true`,[tenant])).rows[0];if(fc){const pts=Math.max(0,Math.floor(Number(fresh.total)*Number(fc.pontos_por_real||1)));if(pts){await c.query(`INSERT INTO fidelidade_saldos(barbearia_id,cliente_id,pontos) VALUES($1,$2,$3) ON CONFLICT(barbearia_id,cliente_id) DO UPDATE SET pontos=fidelidade_saldos.pontos+EXCLUDED.pontos,atualizado_em=NOW()`,[tenant,fresh.cliente_id,pts]);await c.query(`INSERT INTO fidelidade_movimentos(barbearia_id,cliente_id,pontos,tipo,referencia_tipo,referencia_id,descricao) VALUES($1,$2,$3,'credito','venda',$4,'Pontos da comanda')`,[tenant,fresh.cliente_id,pts,vr.id])}}}await c.query(`UPDATE comandas SET status='fechada',forma_pagamento=$1,venda_id=$2,fechada_em=NOW(),atualizado_em=NOW() WHERE id=$3 AND barbearia_id=$4`,[forma,vr.id,id,tenant]);await c.query('COMMIT');res.json({mensagem:'Comanda fechada',venda_id:vr.id,total:Number(fresh.total)})}catch(e){try{await c.query('ROLLBACK')}catch{}console.error('close_comanda',e.message);res.status(400).json({erro:e.message||'Erro ao fechar comanda'})}finally{c.release()}});
router.post('/comandas/:id/cancelar',manager,exigirRecurso('comandas'),exigirStepUp,async(req,res)=>{const id=intId(req.params.id);const r=await pool.query(`UPDATE comandas SET status='cancelada',atualizado_em=NOW() WHERE id=$1 AND barbearia_id=$2 AND status='aberta' RETURNING *`,[id,t(req)]);if(!r.rowCount)return res.status(409).json({erro:'Comanda não pode ser cancelada'});res.json(r.rows[0])});

// ---------- Clube de assinaturas ----------
router.get('/clube/planos',manager,exigirRecurso('clube_assinaturas'),async(req,res)=>{const rows=(await pool.query(`SELECT p.*,COALESCE(json_agg(json_build_object('servico_id',ps.servico_id,'servico',s.nome,'quantidade',ps.quantidade_mensal)) FILTER(WHERE ps.servico_id IS NOT NULL),'[]') servicos FROM clube_planos p LEFT JOIN clube_plano_servicos ps ON ps.plano_id=p.id AND ps.barbearia_id=p.barbearia_id LEFT JOIN servicos s ON s.id=ps.servico_id AND s.barbearia_id=p.barbearia_id WHERE p.barbearia_id=$1 GROUP BY p.id ORDER BY p.ativo DESC,p.nome`,[t(req)])).rows;res.json(rows)});
router.post('/clube/planos',manager,exigirRecurso('clube_assinaturas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const x=req.body||{},nome=cleanText(x.nome,160,{required:true}),preco=money(x.preco_mensal),dia=x.dia_cobranca?Number(x.dia_cobranca):null,servicos=Array.isArray(x.servicos)?x.servicos:[];if(!nome||preco===null||(dia!=null&&(!Number.isInteger(dia)||dia<1||dia>28)))throw new Error('Plano inválido');const p=(await c.query(`INSERT INTO clube_planos(barbearia_id,nome,descricao,preco_mensal,dia_cobranca) VALUES($1,$2,$3,$4,$5) RETURNING *`,[t(req),nome,cleanText(x.descricao,2000)||null,preco,dia])).rows[0];for(const s of servicos){const sid=intId(s.servico_id),q=Number(s.quantidade||1);if(!sid||!Number.isInteger(q)||q<1||q>100)throw new Error('Serviço do plano inválido');if(!(await c.query(`SELECT 1 FROM servicos WHERE id=$1 AND barbearia_id=$2`,[sid,t(req)])).rowCount)throw new Error('Serviço não pertence à barbearia');await c.query(`INSERT INTO clube_plano_servicos(plano_id,barbearia_id,servico_id,quantidade_mensal) VALUES($1,$2,$3,$4)`,[p.id,t(req),sid,q])}await c.query('COMMIT');res.status(201).json(p)}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});
router.get('/clube/assinaturas',manager,exigirRecurso('clube_assinaturas'),async(req,res)=>{const r=await pool.query(`SELECT a.*,c.nome cliente,c.telefone,p.nome plano,p.preco_mensal,(SELECT COALESCE(SUM(cc.quantidade),0)::int FROM clube_consumos cc WHERE cc.assinatura_id=a.id AND cc.competencia=date_trunc('month',CURRENT_DATE)::date) consumos_mes FROM clube_assinaturas a JOIN clientes c ON c.id=a.cliente_id AND c.barbearia_id=a.barbearia_id JOIN clube_planos p ON p.id=a.plano_id AND p.barbearia_id=a.barbearia_id WHERE a.barbearia_id=$1 ORDER BY CASE a.status WHEN 'ativa' THEN 0 ELSE 1 END,a.atualizado_em DESC`,[t(req)]);res.json(r.rows)});
router.post('/clube/assinaturas',manager,exigirRecurso('clube_assinaturas'),async(req,res)=>{try{const cliente=intId(req.body.cliente_id),plano=intId(req.body.plano_id),forma=cleanText(req.body.forma_pagamento,30)||null;if(!cliente||!plano)return res.status(400).json({erro:'Cliente e plano são obrigatórios'});if(!(await pool.query(`SELECT 1 FROM clientes WHERE id=$1 AND barbearia_id=$2`,[cliente,t(req)])).rowCount)return res.status(400).json({erro:'Cliente inválido'});const p=(await pool.query(`SELECT * FROM clube_planos WHERE id=$1 AND barbearia_id=$2 AND ativo=true`,[plano,t(req)])).rows[0];if(!p)return res.status(400).json({erro:'Plano inválido'});const r=await pool.query(`INSERT INTO clube_assinaturas(barbearia_id,cliente_id,plano_id,status,inicio,proxima_cobranca,forma_pagamento) VALUES($1,$2,$3,'ativa',CURRENT_DATE,(date_trunc('month',CURRENT_DATE)+INTERVAL '1 month'+((CASE WHEN $4::int BETWEEN 1 AND 28 THEN $4::int ELSE EXTRACT(DAY FROM CURRENT_DATE)::int END)-1)*INTERVAL '1 day')::date,$5) RETURNING *`,[t(req),cliente,plano,p.dia_cobranca||new Date().getDate(),forma]);await pool.query(`INSERT INTO clube_cobrancas(barbearia_id,assinatura_id,competencia,vencimento,valor,status,forma_pagamento) VALUES($1,$2,date_trunc('month',CURRENT_DATE)::date,CURRENT_DATE,$3,'pendente',$4) ON CONFLICT(assinatura_id,competencia) DO NOTHING`,[t(req),r.rows[0].id,Number(p.preco_mensal||0),forma]);res.status(201).json(r.rows[0])}catch(e){console.error(e);res.status(400).json({erro:'Não foi possível criar assinatura'})}});
router.patch('/clube/assinaturas/:id',manager,exigirRecurso('clube_assinaturas'),async(req,res)=>{const id=intId(req.params.id),status=String(req.body.status||'');if(!id||!['ativa','pausada','inadimplente','cancelada'].includes(status))return res.status(400).json({erro:'Status inválido'});const r=await pool.query(`UPDATE clube_assinaturas SET status=$1,atualizado_em=NOW() WHERE id=$2 AND barbearia_id=$3 RETURNING *`,[status,id,t(req)]);if(!r.rowCount)return res.status(404).json({erro:'Assinatura não encontrada'});res.json(r.rows[0])});
router.post('/clube/assinaturas/:id/consumir',staff,exigirRecurso('clube_assinaturas'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=intId(req.params.id),sid=intId(req.body.servico_id),q=Number(req.body.quantidade||1),ag=req.body.agendamento_id?intId(req.body.agendamento_id):null;if(!id||!sid||!Number.isInteger(q)||q<1)throw new Error('Consumo inválido');const a=(await c.query(`SELECT a.*,ps.quantidade_mensal FROM clube_assinaturas a JOIN clube_plano_servicos ps ON ps.plano_id=a.plano_id AND ps.servico_id=$2 AND ps.barbearia_id=a.barbearia_id WHERE a.id=$1 AND a.barbearia_id=$3 AND a.status='ativa' FOR UPDATE`,[id,sid,t(req)])).rows[0];if(!a)throw new Error('Assinatura ativa não inclui este serviço');const used=Number((await c.query(`SELECT COALESCE(SUM(quantidade),0) n FROM clube_consumos WHERE assinatura_id=$1 AND servico_id=$2 AND competencia=date_trunc('month',CURRENT_DATE)::date`,[id,sid])).rows[0].n);if(used+q>Number(a.quantidade_mensal))throw new Error('Franquia mensal deste serviço esgotada');const r=(await c.query(`INSERT INTO clube_consumos(barbearia_id,assinatura_id,servico_id,agendamento_id,quantidade) VALUES($1,$2,$3,$4,$5) RETURNING *`,[t(req),id,sid,ag||null,q])).rows[0];await c.query('COMMIT');res.status(201).json(r)}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});

// ---------- Pacotes e fidelidade ----------
router.post('/pacotes/:id/vender',manager,exigirRecurso('fidelidade'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const pacote=intId(req.params.id),cliente=intId(req.body.cliente_id),tenant=t(req);const p=(await c.query(`SELECT * FROM pacotes WHERE id=$1 AND barbearia_id=$2 AND ativo=true`,[pacote,tenant])).rows[0];if(!p||!cliente)throw new Error('Pacote/cliente inválido');if(!(await c.query(`SELECT 1 FROM clientes WHERE id=$1 AND barbearia_id=$2`,[cliente,tenant])).rowCount)throw new Error('Cliente inválido');let srv=(await c.query(`SELECT * FROM pacote_servicos WHERE pacote_id=$1 AND barbearia_id=$2`,[pacote,tenant])).rows;if(!srv.length&&req.body.servico_id){const sid=intId(req.body.servico_id),q=Number(req.body.quantidade||1);if(!sid||!Number.isInteger(q)||q<1)throw new Error('Serviço inválido');await c.query(`INSERT INTO pacote_servicos(pacote_id,barbearia_id,servico_id,quantidade) VALUES($1,$2,$3,$4) ON CONFLICT(pacote_id,servico_id) DO UPDATE SET quantidade=EXCLUDED.quantidade`,[pacote,tenant,sid,q]);srv=[{servico_id:sid,quantidade:q}]}if(!srv.length)throw new Error('Configure os serviços do pacote');const cp=(await c.query(`INSERT INTO cliente_pacotes(barbearia_id,cliente_id,pacote_id,valor_pago,expira_em) VALUES($1,$2,$3,$4,CURRENT_DATE+($5*INTERVAL '1 day')) RETURNING *`,[tenant,cliente,pacote,Number(p.preco||0),Number(p.validade_dias||90)])).rows[0];for(const s of srv)await c.query(`INSERT INTO cliente_pacote_saldos(cliente_pacote_id,barbearia_id,servico_id,quantidade_total) VALUES($1,$2,$3,$4)`,[cp.id,tenant,s.servico_id,s.quantidade]);await c.query('COMMIT');res.status(201).json(cp)}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});
router.get('/pacotes/cliente/:clienteId',staff,exigirRecurso('fidelidade'),async(req,res)=>{const cid=intId(req.params.clienteId);if(!cid)return res.status(400).json({erro:'Cliente inválido'});const r=await pool.query(`SELECT cp.*,p.nome,p.preco,COALESCE(json_agg(json_build_object('servico_id',s.id,'servico',s.nome,'total',ps.quantidade_total,'usada',ps.quantidade_usada,'restante',ps.quantidade_total-ps.quantidade_usada)) FILTER(WHERE s.id IS NOT NULL),'[]') saldos FROM cliente_pacotes cp JOIN pacotes p ON p.id=cp.pacote_id AND p.barbearia_id=cp.barbearia_id LEFT JOIN cliente_pacote_saldos ps ON ps.cliente_pacote_id=cp.id AND ps.barbearia_id=cp.barbearia_id LEFT JOIN servicos s ON s.id=ps.servico_id AND s.barbearia_id=cp.barbearia_id WHERE cp.barbearia_id=$1 AND cp.cliente_id=$2 GROUP BY cp.id,p.id ORDER BY cp.comprado_em DESC`,[t(req),cid]);res.json(r.rows)});
router.post('/pacotes/cliente/:clientePacoteId/consumir',staff,exigirRecurso('fidelidade'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=intId(req.params.clientePacoteId),sid=intId(req.body.servico_id),q=Number(req.body.quantidade||1);if(!id||!sid||!Number.isInteger(q)||q<1)throw new Error('Consumo inválido');const cp=(await c.query(`SELECT * FROM cliente_pacotes WHERE id=$1 AND barbearia_id=$2 AND status='ativo' FOR UPDATE`,[id,t(req)])).rows[0];if(!cp||cp.expira_em&&String(cp.expira_em).slice(0,10)<new Date().toISOString().slice(0,10))throw new Error('Pacote inativo ou expirado');const s=(await c.query(`SELECT * FROM cliente_pacote_saldos WHERE cliente_pacote_id=$1 AND barbearia_id=$2 AND servico_id=$3 FOR UPDATE`,[id,t(req),sid])).rows[0];if(!s||Number(s.quantidade_usada)+q>Number(s.quantidade_total))throw new Error('Saldo insuficiente');await c.query(`UPDATE cliente_pacote_saldos SET quantidade_usada=quantidade_usada+$1 WHERE cliente_pacote_id=$2 AND servico_id=$3`,[q,id,sid]);const left=Number((await c.query(`SELECT COALESCE(SUM(quantidade_total-quantidade_usada),0) n FROM cliente_pacote_saldos WHERE cliente_pacote_id=$1`,[id])).rows[0].n);if(left<=0)await c.query(`UPDATE cliente_pacotes SET status='consumido',atualizado_em=NOW() WHERE id=$1`,[id]);await c.query('COMMIT');res.json({mensagem:'Serviço consumido',restante_total:left})}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});
router.get('/fidelidade/cliente/:clienteId',staff,exigirRecurso('fidelidade'),async(req,res)=>{const cid=intId(req.params.clienteId);const [s,m]=await Promise.all([pool.query(`SELECT pontos FROM fidelidade_saldos WHERE barbearia_id=$1 AND cliente_id=$2`,[t(req),cid]),pool.query(`SELECT * FROM fidelidade_movimentos WHERE barbearia_id=$1 AND cliente_id=$2 ORDER BY criado_em DESC LIMIT 100`,[t(req),cid])]);res.json({pontos:Number(s.rows[0]?.pontos||0),movimentos:m.rows})});
router.post('/fidelidade/cliente/:clienteId/movimentos',manager,exigirRecurso('fidelidade'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const cid=intId(req.params.clienteId),pts=Number(req.body.pontos),tipo=String(req.body.tipo||'ajuste'),desc=cleanText(req.body.descricao,220)||'Ajuste manual';if(!cid||!Number.isInteger(pts)||pts===0||Math.abs(pts)>1_000_000)throw new Error('Movimento inválido');const row=(await c.query(`SELECT pontos FROM fidelidade_saldos WHERE barbearia_id=$1 AND cliente_id=$2 FOR UPDATE`,[t(req),cid])).rows[0],atual=Number(row?.pontos||0);if(atual+pts<0)throw new Error('Saldo insuficiente');await c.query(`INSERT INTO fidelidade_saldos(barbearia_id,cliente_id,pontos) VALUES($1,$2,$3) ON CONFLICT(barbearia_id,cliente_id) DO UPDATE SET pontos=fidelidade_saldos.pontos+$3,atualizado_em=NOW()`,[t(req),cid,pts]);await c.query(`INSERT INTO fidelidade_movimentos(barbearia_id,cliente_id,pontos,tipo,descricao) VALUES($1,$2,$3,$4,$5)`,[t(req),cid,pts,tipo,desc]);await c.query('COMMIT');res.json({pontos:atual+pts})}catch(e){try{await c.query('ROLLBACK')}catch{}res.status(400).json({erro:e.message})}finally{c.release()}});

// ---------- CRM avançado ----------
router.get('/crm',manager,exigirRecurso('crm_avancado'),async(req,res)=>{try{const r=await pool.query(`WITH hist AS (SELECT c.id,COUNT(a.id) FILTER(WHERE a.status='concluido')::int visitas,COUNT(a.id) FILTER(WHERE a.status='nao_compareceu')::int faltas,COALESCE(SUM(COALESCE(a.valor_final,a.valor_servico,0)) FILTER(WHERE a.status='concluido'),0)::numeric total,MAX(a.data) FILTER(WHERE a.status='concluido') ultima,MIN(a.data) FILTER(WHERE a.status='concluido') primeira FROM clientes c LEFT JOIN agendamentos a ON a.cliente_id=c.id AND a.barbearia_id=c.barbearia_id WHERE c.barbearia_id=$1 GROUP BY c.id) SELECT c.id,c.nome,c.telefone,c.email,c.criado_em,h.visitas,h.faltas,h.total total_gasto,h.ultima ultima_visita,CASE WHEN h.visitas=0 THEN 'novo' WHEN h.total>=1000 OR h.visitas>=10 THEN 'vip' WHEN h.ultima<CURRENT_DATE-INTERVAL '90 days' THEN 'inativo' WHEN h.ultima<CURRENT_DATE-INTERVAL '45 days' THEN 'risco' ELSE 'fiel' END segmento,COALESCE(fs.pontos,0)::int pontos,COALESCE(json_agg(DISTINCT tg.nome) FILTER(WHERE tg.id IS NOT NULL),'[]') tags FROM clientes c JOIN hist h ON h.id=c.id LEFT JOIN fidelidade_saldos fs ON fs.barbearia_id=c.barbearia_id AND fs.cliente_id=c.id LEFT JOIN crm_cliente_tags ct ON ct.barbearia_id=c.barbearia_id AND ct.cliente_id=c.id LEFT JOIN crm_tags tg ON tg.id=ct.tag_id AND tg.barbearia_id=c.barbearia_id WHERE c.barbearia_id=$1 GROUP BY c.id,h.visitas,h.faltas,h.total,h.ultima,fs.pontos ORDER BY h.total DESC,c.nome LIMIT 1000`,[t(req)]);res.json(r.rows)}catch(e){console.error(e);res.status(500).json({erro:'Erro ao carregar CRM avançado'})}});
router.get('/crm/:id',manager,exigirRecurso('crm_avancado'),async(req,res)=>{try{const id=intId(req.params.id);const c=(await pool.query(`SELECT * FROM clientes WHERE id=$1 AND barbearia_id=$2`,[id,t(req)])).rows[0];if(!c)return res.status(404).json({erro:'Cliente não encontrado'});const [hist,metrics,tags,club,packages,fid]=await Promise.all([pool.query(`SELECT a.id,a.data,a.horario,a.status,s.nome servico,b.nome barbeiro,COALESCE(a.valor_final,a.valor_servico,s.preco) valor FROM agendamentos a JOIN servicos s ON s.id=a.servico_id AND s.barbearia_id=a.barbearia_id JOIN barbeiros b ON b.id=a.barbeiro_id AND b.barbearia_id=a.barbearia_id WHERE a.barbearia_id=$1 AND a.cliente_id=$2 ORDER BY a.data DESC,a.horario DESC LIMIT 150`,[t(req),id]),pool.query(`SELECT COUNT(*) FILTER(WHERE status='concluido')::int visitas,COUNT(*) FILTER(WHERE status='nao_compareceu')::int faltas,COALESCE(SUM(COALESCE(valor_final,valor_servico,0)) FILTER(WHERE status='concluido'),0)::numeric total_gasto,COALESCE(AVG(COALESCE(valor_final,valor_servico,0)) FILTER(WHERE status='concluido'),0)::numeric ticket_medio,MAX(data) FILTER(WHERE status='concluido') ultima_visita,ROUND(AVG(diff))::int frequencia_dias FROM (SELECT a.*,a.data-LAG(a.data) OVER(ORDER BY a.data) diff FROM agendamentos a WHERE barbearia_id=$1 AND cliente_id=$2 AND status='concluido') z`,[t(req),id]),pool.query(`SELECT tg.* FROM crm_tags tg JOIN crm_cliente_tags ct ON ct.tag_id=tg.id AND ct.barbearia_id=tg.barbearia_id WHERE ct.barbearia_id=$1 AND ct.cliente_id=$2 ORDER BY tg.nome`,[t(req),id]),pool.query(`SELECT a.status,p.nome,p.preco_mensal,a.proxima_cobranca FROM clube_assinaturas a JOIN clube_planos p ON p.id=a.plano_id AND p.barbearia_id=a.barbearia_id WHERE a.barbearia_id=$1 AND a.cliente_id=$2 ORDER BY a.atualizado_em DESC`,[t(req),id]),pool.query(`SELECT cp.id,cp.status,cp.expira_em,p.nome,p.preco FROM cliente_pacotes cp JOIN pacotes p ON p.id=cp.pacote_id AND p.barbearia_id=cp.barbearia_id WHERE cp.barbearia_id=$1 AND cp.cliente_id=$2 ORDER BY cp.comprado_em DESC`,[t(req),id]),pool.query(`SELECT pontos FROM fidelidade_saldos WHERE barbearia_id=$1 AND cliente_id=$2`,[t(req),id])]);res.json({cliente:c,metricas:metrics.rows[0],historico:hist.rows,tags:tags.rows,clube:club.rows,pacotes:packages.rows,fidelidade:{pontos:Number(fid.rows[0]?.pontos||0)}})}catch(e){console.error(e);res.status(500).json({erro:'Erro ao carregar cliente'})}});
router.get('/crm-tags',manager,exigirRecurso('crm_avancado'),async(req,res)=>{res.json((await pool.query(`SELECT * FROM crm_tags WHERE barbearia_id=$1 ORDER BY nome`,[t(req)])).rows)});
router.post('/crm-tags',manager,exigirRecurso('crm_avancado'),async(req,res)=>{try{const nome=cleanText(req.body.nome,60,{required:true});if(!nome)return res.status(400).json({erro:'Nome obrigatório'});const r=await pool.query(`INSERT INTO crm_tags(barbearia_id,nome) VALUES($1,$2) ON CONFLICT(barbearia_id,nome) DO UPDATE SET nome=EXCLUDED.nome RETURNING *`,[t(req),nome]);res.status(201).json(r.rows[0])}catch(e){res.status(400).json({erro:'Erro ao criar etiqueta'})}});
router.post('/crm/:clienteId/tags/:tagId',manager,exigirRecurso('crm_avancado'),async(req,res)=>{const cid=intId(req.params.clienteId),tag=intId(req.params.tagId);if(!cid||!tag)return res.status(400).json({erro:'Dados inválidos'});const ok=await pool.query(`INSERT INTO crm_cliente_tags(barbearia_id,cliente_id,tag_id) SELECT $1,c.id,tg.id FROM clientes c,crm_tags tg WHERE c.id=$2 AND c.barbearia_id=$1 AND tg.id=$3 AND tg.barbearia_id=$1 ON CONFLICT DO NOTHING RETURNING *`,[t(req),cid,tag]);if(!ok.rowCount)return res.status(404).json({erro:'Cliente/tag não encontrado'});res.status(201).json(ok.rows[0])});
router.delete('/crm/:clienteId/tags/:tagId',manager,exigirRecurso('crm_avancado'),async(req,res)=>{await pool.query(`DELETE FROM crm_cliente_tags WHERE barbearia_id=$1 AND cliente_id=$2 AND tag_id=$3`,[t(req),intId(req.params.clienteId),intId(req.params.tagId)]);res.json({mensagem:'Etiqueta removida'})});

// ---------- Fila inteligente ----------
router.get('/fila',staff,exigirRecurso('fila_espera'),async(req,res)=>{const r=await pool.query(`SELECT f.*,c.nome cliente,c.telefone,b.nome barbeiro,s.nome servico FROM fila_espera f JOIN clientes c ON c.id=f.cliente_id AND c.barbearia_id=f.barbearia_id LEFT JOIN barbeiros b ON b.id=f.barbeiro_id AND b.barbearia_id=f.barbearia_id JOIN servicos s ON s.id=f.servico_id AND s.barbearia_id=f.barbearia_id WHERE f.barbearia_id=$1 AND f.status IN ('aguardando','notificado') ORDER BY f.prioridade DESC,f.criado_em`,[t(req)]);res.json(r.rows)});
router.post('/fila',staff,exigirRecurso('fila_espera'),async(req,res)=>{try{const x=req.body||{},cid=intId(x.cliente_id),sid=intId(x.servico_id),bid=x.barbeiro_id?intId(x.barbeiro_id):null,data=x.data_preferida?String(x.data_preferida):null,prio=Math.max(0,Math.min(100,Number(x.prioridade||0)));if(!cid||!sid||(data&&!isoDate(data)))return res.status(400).json({erro:'Dados da fila inválidos'});const r=await pool.query(`INSERT INTO fila_espera(barbearia_id,cliente_id,barbeiro_id,servico_id,observacoes,data_preferida,hora_inicio,hora_fim,prioridade,origem) SELECT $1,c.id,$3,s.id,$4,$5,$6,$7,$8,'painel' FROM clientes c,servicos s WHERE c.id=$2 AND c.barbearia_id=$1 AND s.id=$9 AND s.barbearia_id=$1 AND s.ativo=true RETURNING *`,[t(req),cid,bid,cleanText(x.observacoes,1000)||null,data,x.hora_inicio||null,x.hora_fim||null,prio,sid]);if(!r.rowCount)return res.status(400).json({erro:'Cliente/serviço inválido'});res.status(201).json(r.rows[0])}catch(e){res.status(400).json({erro:'Não foi possível adicionar à fila'})}});
router.post('/fila/:id/notificar',staff,exigirRecurso('fila_espera'),async(req,res)=>{const id=intId(req.params.id),row=(await pool.query(`SELECT * FROM fila_espera WHERE id=$1 AND barbearia_id=$2`,[id,t(req)])).rows[0];if(!row)return res.status(404).json({erro:'Item não encontrado'});const n=await notifyWaitlistForSlot({barbeariaId:t(req),barbeiroId:row.barbeiro_id,servicoId:row.servico_id,data:req.body.data||row.data_preferida,horario:req.body.horario||row.hora_inicio});res.json({notificados:n})});
router.patch('/fila/:id',staff,exigirRecurso('fila_espera'),async(req,res)=>{const id=intId(req.params.id),status=String(req.body.status||'');if(!id||!['aguardando','notificado','atendido','cancelado'].includes(status))return res.status(400).json({erro:'Status inválido'});const r=await pool.query(`UPDATE fila_espera SET status=$1,atualizado_em=NOW() WHERE id=$2 AND barbearia_id=$3 RETURNING *`,[status,id,t(req)]);if(!r.rowCount)return res.status(404).json({erro:'Item não encontrado'});res.json(r.rows[0])});

// ---------- BI ----------
router.get('/bi/resumo',manager,exigirRecurso('bi_avancado'),async(req,res)=>{try{const tenant=t(req),inicio=isoDate(req.query.inicio)?req.query.inicio:new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10),fim=isoDate(req.query.fim)?req.query.fim:new Date().toISOString().slice(0,10);const [agenda,vendas,topb,tops,trend,club,wait,stock,newret,pay]=await Promise.all([
 pool.query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='concluido')::int concluidos,COUNT(*) FILTER(WHERE status='cancelado')::int cancelados,COUNT(*) FILTER(WHERE status='nao_compareceu')::int no_show,COUNT(DISTINCT cliente_id) FILTER(WHERE status='concluido')::int clientes,COALESCE(SUM(COALESCE(valor_final,valor_servico,0)) FILTER(WHERE status='concluido'),0)::numeric receita_servicos FROM agendamentos WHERE barbearia_id=$1 AND data BETWEEN $2 AND $3`,[tenant,inicio,fim]),
 pool.query(`SELECT COALESCE(SUM(total),0)::numeric receita,COALESCE(AVG(total),0)::numeric ticket,COALESCE(SUM(subtotal_produtos),0)::numeric produtos,COALESCE(SUM(subtotal_servicos),0)::numeric servicos,COUNT(*)::int vendas FROM vendas WHERE barbearia_id=$1 AND status='finalizada' AND criado_em::date BETWEEN $2 AND $3`,[tenant,inicio,fim]),
 pool.query(`SELECT b.nome,COUNT(a.id) FILTER(WHERE a.status='concluido')::int atendimentos,COALESCE(SUM(COALESCE(a.valor_final,a.valor_servico,0)) FILTER(WHERE a.status='concluido'),0)::numeric receita FROM barbeiros b LEFT JOIN agendamentos a ON a.barbeiro_id=b.id AND a.barbearia_id=b.barbearia_id AND a.data BETWEEN $2 AND $3 WHERE b.barbearia_id=$1 GROUP BY b.id ORDER BY receita DESC LIMIT 5`,[tenant,inicio,fim]),
 pool.query(`SELECT s.nome,COUNT(a.id) FILTER(WHERE a.status='concluido')::int quantidade,COALESCE(SUM(COALESCE(a.valor_final,a.valor_servico,0)) FILTER(WHERE a.status='concluido'),0)::numeric receita FROM servicos s LEFT JOIN agendamentos a ON a.servico_id=s.id AND a.barbearia_id=s.barbearia_id AND a.data BETWEEN $2 AND $3 WHERE s.barbearia_id=$1 GROUP BY s.id ORDER BY quantidade DESC LIMIT 5`,[tenant,inicio,fim]),
 pool.query(`SELECT d::date data,COALESCE(SUM(v.total),0)::numeric receita FROM generate_series($2::date,$3::date,'1 day') d LEFT JOIN vendas v ON v.barbearia_id=$1 AND v.status='finalizada' AND v.criado_em::date=d::date GROUP BY d ORDER BY d`,[tenant,inicio,fim]),
 pool.query(`SELECT COUNT(*) FILTER(WHERE status='ativa')::int ativas,COUNT(*) FILTER(WHERE status='inadimplente')::int inadimplentes,COALESCE(SUM(p.preco_mensal) FILTER(WHERE a.status='ativa'),0)::numeric mrr FROM clube_assinaturas a JOIN clube_planos p ON p.id=a.plano_id AND p.barbearia_id=a.barbearia_id WHERE a.barbearia_id=$1`,[tenant]),
 pool.query(`SELECT COUNT(*) FILTER(WHERE status='aguardando')::int aguardando,COUNT(*) FILTER(WHERE status='notificado')::int notificados FROM fila_espera WHERE barbearia_id=$1`,[tenant]),
 pool.query(`SELECT COUNT(*) FILTER(WHERE ativo AND estoque<=estoque_minimo)::int baixo,COALESCE(SUM(custo*estoque) FILTER(WHERE ativo),0)::numeric valor FROM produtos WHERE barbearia_id=$1`,[tenant]),
 pool.query(`SELECT COUNT(DISTINCT a.cliente_id) FILTER(WHERE NOT EXISTS(SELECT 1 FROM agendamentos old WHERE old.barbearia_id=a.barbearia_id AND old.cliente_id=a.cliente_id AND old.status='concluido' AND old.data<$2))::int novos,COUNT(DISTINCT a.cliente_id) FILTER(WHERE EXISTS(SELECT 1 FROM agendamentos old WHERE old.barbearia_id=a.barbearia_id AND old.cliente_id=a.cliente_id AND old.status='concluido' AND old.data<$2))::int recorrentes FROM agendamentos a WHERE a.barbearia_id=$1 AND a.status='concluido' AND a.data BETWEEN $2 AND $3`,[tenant,inicio,fim]),
 pool.query(`SELECT COALESCE(forma_pagamento,'não informado') forma,COUNT(*)::int quantidade,COALESCE(SUM(total),0)::numeric total FROM vendas WHERE barbearia_id=$1 AND status='finalizada' AND criado_em::date BETWEEN $2 AND $3 GROUP BY forma_pagamento ORDER BY total DESC`,[tenant,inicio,fim])]);
 const a=agenda.rows[0],v=vendas.rows[0],taxa=Number(a.total)>0?Number(a.concluidos)/Number(a.total)*100:0,noShow=Number(a.total)>0?Number(a.no_show)/Number(a.total)*100:0;res.json({periodo:{inicio,fim},kpis:{agendamentos:Number(a.total),concluidos:Number(a.concluidos),cancelados:Number(a.cancelados),no_show:Number(a.no_show),taxa_conclusao:Number(taxa.toFixed(1)),taxa_no_show:Number(noShow.toFixed(1)),receita:Number(v.receita||0),ticket_medio:Number(v.ticket||0),receita_produtos:Number(v.produtos||0),receita_servicos:Number(v.servicos||0),vendas:Number(v.vendas||0),clientes:Number(a.clientes||0),clientes_novos:Number(newret.rows[0].novos||0),clientes_recorrentes:Number(newret.rows[0].recorrentes||0)},clube:club.rows[0],fila:wait.rows[0],estoque:stock.rows[0],top_barbeiros:topb.rows,top_servicos:tops.rows,tendencia:trend.rows,pagamentos:pay.rows})}catch(e){console.error(e);res.status(500).json({erro:'Erro ao calcular BI'})}});


