router.post('/fiscal/documentos',manager,exigirRecurso('fiscal_nfse'),async(req,res)=>{try{const venda=intId(req.body.venda_id);if(!venda)return res.status(400).json({erro:'Venda obrigatória'});const v=(await pool.query(`SELECT v.*,c.nome cliente,c.email,c.telefone FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id AND c.barbearia_id=v.barbearia_id WHERE v.id=$1 AND v.barbearia_id=$2 AND v.status='finalizada'`,[venda,t(req)])).rows[0];if(!v)return res.status(404).json({erro:'Venda não encontrada'});const desc=(await pool.query(`SELECT string_agg(descricao||' x'||quantidade,', ') d FROM venda_itens WHERE venda_id=$1`,[venda])).rows[0].d||'Serviços de barbearia';const r=await pool.query(`INSERT INTO fiscal_documentos(barbearia_id,venda_id,valor,descricao,payload) VALUES($1,$2,$3,$4,$5) RETURNING *`,[t(req),venda,Number(v.subtotal_servicos||v.total||0),desc,JSON.stringify({cliente:{nome:v.cliente,email:v.email,telefone:v.telefone},venda_id:venda})]);res.status(201).json(r.rows[0])}catch(e){res.status(400).json({erro:'Não foi possível preparar documento'})}});
router.post('/fiscal/documentos/:id/emitir',manager,exigirRecurso('fiscal_nfse'),exigirStepUp,async(req,res)=>{try{const id=intId(req.params.id),tenant=t(req),cfg=(await pool.query(`SELECT * FROM fiscal_config WHERE barbearia_id=$1 AND ativo=true`,[tenant])).rows[0],doc=(await pool.query(`SELECT * FROM fiscal_documentos WHERE id=$1 AND barbearia_id=$2`,[id,tenant])).rows[0];if(!doc)return res.status(404).json({erro:'Documento não encontrado'});if(!cfg)return res.status(400).json({erro:'Configure a emissão fiscal primeiro'});if(cfg.provedor==='manual')return res.status(409).json({erro:'Documento preparado. Para emissão automática, configure um provedor NFS-e compatível e as credenciais fiscais da empresa.',preparado:true});const url=safeHttpUrl(process.env.NFSE_API_URL);if(!url||url===false||!/^https:/.test(url))return res.status(503).json({erro:'NFSE_API_URL HTTPS não configurada'});await pool.query(`UPDATE fiscal_documentos SET status='processando',atualizado_em=NOW() WHERE id=$1 AND barbearia_id=$2`,[id,tenant]);const headers={'Content-Type':'application/json'};if(process.env.NFSE_API_TOKEN)headers.Authorization=`Bearer ${process.env.NFSE_API_TOKEN}`;const response=await fetch(url,{method:'POST',headers,signal:externalSignal(),body:JSON.stringify({tenant_id:tenant,documento:{id:doc.id,valor:Number(doc.valor),descricao:doc.descricao,payload:doc.payload},config:{regime:cfg.regime,codigo_servico:cfg.codigo_servico,item_lista_servico:cfg.item_lista_servico,aliquota_iss:cfg.aliquota_iss,municipio_codigo:cfg.municipio_codigo,inscricao_municipal:cfg.inscricao_municipal}})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.erro||body.message||`Provedor NFS-e HTTP ${response.status}`);const r=await pool.query(`UPDATE fiscal_documentos SET status='emitida',numero=$1,codigo_verificacao=$2,url=$3,provider_id=$4,payload=payload||$5::jsonb,emitido_em=NOW(),atualizado_em=NOW(),erro=NULL WHERE id=$6 AND barbearia_id=$7 RETURNING *`,[cleanText(body.numero,80)||null,cleanText(body.codigo_verificacao,120)||null,safeHttpUrl(body.url)||null,cleanText(body.id||body.provider_id,160)||null,JSON.stringify({provider_response:body}),id,tenant]);res.json(r.rows[0])}catch(e){console.error('nfse_emit',e.message);await pool.query(`UPDATE fiscal_documentos SET status='erro',erro=$1,atualizado_em=NOW() WHERE id=$2 AND barbearia_id=$3`,[cleanText(e.message,500),intId(req.params.id),t(req)]).catch(()=>{});res.status(502).json({erro:e.message||'Falha ao emitir NFS-e'})}});

// ---------- Oportunidades de marketing ----------
router.get('/marketing/oportunidades',manager,exigirRecurso('marketing_inteligente'),async(req,res)=>{try{const tenant=t(req);const [inactive,birth,due,wait,tomorrow]=await Promise.all([pool.query(`SELECT COUNT(*)::int n FROM clientes c WHERE c.barbearia_id=$1 AND c.marketing_opt_in=true AND EXISTS(SELECT 1 FROM agendamentos a WHERE a.barbearia_id=c.barbearia_id AND a.cliente_id=c.id AND a.status='concluido') AND (SELECT MAX(a.data) FROM agendamentos a WHERE a.barbearia_id=c.barbearia_id AND a.cliente_id=c.id AND a.status='concluido')<CURRENT_DATE-INTERVAL '45 days'`,[tenant]),pool.query(`SELECT COUNT(*)::int n FROM clientes WHERE barbearia_id=$1 AND marketing_opt_in=true AND data_nascimento IS NOT NULL AND EXTRACT(MONTH FROM data_nascimento)=EXTRACT(MONTH FROM CURRENT_DATE+INTERVAL '7 days')`,[tenant]),pool.query(`WITH h AS (SELECT cliente_id,MAX(data) ultima,AVG(diff) freq FROM (SELECT cliente_id,data,data-LAG(data) OVER(PARTITION BY cliente_id ORDER BY data) diff FROM agendamentos WHERE barbearia_id=$1 AND status='concluido') x GROUP BY cliente_id) SELECT COUNT(*)::int n FROM h JOIN clientes c ON c.id=h.cliente_id AND c.barbearia_id=$1 WHERE c.marketing_opt_in=true AND h.freq IS NOT NULL AND h.ultima+(h.freq*INTERVAL '1 day')<=CURRENT_DATE+INTERVAL '7 days'`,[tenant]),pool.query(`SELECT COUNT(*)::int n FROM fila_espera WHERE barbearia_id=$1 AND status='aguardando'`,[tenant]),pool.query(`SELECT COUNT(*)::int n FROM agendamentos WHERE barbearia_id=$1 AND data=CURRENT_DATE+1 AND status NOT IN ('cancelado','nao_compareceu')`,[tenant])]);const list=[{id:'recuperar_inativos',titulo:'Recuperar clientes inativos',publico:Number(inactive.rows[0].n),segmento:'inativos',mensagem:'Sentimos sua falta! Que tal reservar seu próximo horário?'},{id:'aniversariantes',titulo:'Aniversariantes próximos',publico:Number(birth.rows[0].n),segmento:'aniversariantes',mensagem:'Seu aniversário está chegando 🎉 Temos um convite especial para você.'},{id:'hora_de_voltar',titulo:'Clientes na hora de voltar',publico:Number(due.rows[0].n),segmento:'frequentes',mensagem:'Já está chegando a hora do próximo corte. Quer reservar seu horário?'},{id:'fila',titulo:'Clientes aguardando encaixe',publico:Number(wait.rows[0].n),segmento:'fila',mensagem:'Surgiu um horário e você está na nossa fila de espera.'}];const amanha=Number(tomorrow.rows[0].n);res.json({oportunidades:list.filter(x=>x.publico>0),insight:amanha<5?`Amanhã há apenas ${amanha} agendamento(s). Considere uma campanha para clientes com opt-in.`:`Amanhã já possui ${amanha} agendamentos.`})}catch(e){console.error(e);res.status(500).json({erro:'Erro ao gerar oportunidades'})}});

module.exports=router;
